def get_opening_transformations(conn_header: ConnHeader, params: GetOpeningTransformationsParameters) -> dict:
    """
    Gets the placement of Opening elements, Windows, Doors and Skylights without changing them: a global-to-local
    transformation matrix, its inverse, and the origin and axes in world coordinates derived from the inverse. For
    Windows, Doors and Skylights the local-to-global matrix is the one Archicad returns, and mirrored ones give a left-
    handed matrix (isMirrored). For Opening elements it is built from the opening geometry (Archicad 29 and later):
    origin at the anchor point, the X and Y axes of the opening and Z = X × Y, which points against the extrusion
    direction. Needs Archicad 27 or later.
    """
    return conn_header.core.post_tapir_command(
        command="GetOpeningTransformations", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


